import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.DvE3tBec.js";const n="/assets/arch.DcU9UNsN.png",m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/1.0/developers/arch.md","filePath":"documentation/1.0/developers/arch.md","lastUpdated":1652109416000}'),c={name:"documentation/1.0/developers/arch.md"};function s(o,e,d,h,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>The openEO API defines a language for how clients communicate to back-ends in order to analyze large Earth observation datasets. The API will be implemented by drivers for specific back-ends. Some first architecture considerations are listed below.</p><ol><li>The openEO API is a contract between clients and back-ends that describes the communication only</li><li>Each back-end runs its own API instance including the specific back-end driver. There is no API instance that runs more than one driver.</li><li>Clients in R, Python, and JavaScript connect directly to the back-ends and communicate with the back-ends over <em>HTTPS</em> according to the openEO API specification.</li><li>API instances can run on back-end servers or additional intermediate layers, which then communicate to back-ends in a back-end specific way.</li><li>Back-ends may add functionality and extend the API wherever there is need.</li><li>There will be a central back-end registry service (openEO Hub), to allow users to search for back-ends with specific functionality and or data.</li><li>The openEO API may define <em>profiles</em> in order to group specific functionality.</li></ol><p><img src="'+n+'" alt="Architecture - openEO API shown in dark blue"></p><h1 id="microservices" tabindex="-1">Microservices <a class="header-anchor" href="#microservices" aria-label="Permalink to &quot;Microservices&quot;">​</a></h1><p>To simplify and structure the development, the API is divided into a few microservices.</p><table tabindex="0"><thead><tr><th>Microservice</th><th>Description</th></tr></thead><tbody><tr><td>Capabilities</td><td>This microservice reports on the capabilities of the back-end, i.e. which API endpoints are implemented, which authentication methods are supported, and whether and how UDFs can be executed at the back-end.</td></tr><tr><td>EO Data Discovery</td><td>Describes which collections are available at the back-end.</td></tr><tr><td>Process Discovery</td><td>Provides services to find out which processes a back-end provides, i.e., what users can do with the available data.</td></tr><tr><td>Data Processing</td><td>Organizes and manages data processing on the back-end, either as synchronous on-demand computation or batch jobs.</td></tr><tr><td>File Storage</td><td>Organizes and manages user-uploaded files.</td></tr><tr><td>User-Defined Processes</td><td>Organizes and manages user-defined processes (process graphs).</td></tr><tr><td>Secondary Services</td><td>External web services to access data and job results such as a OGC WMTS service.</td></tr><tr><td>Account Management</td><td>User management, accounting and authentication.</td></tr><tr><td>UDF Runtime</td><td>Execution of user-defined functions, not part of the Core API. See the <a href="./../udfs.html">UDF documentation</a> for more information.</td></tr></tbody></table>',7)])])}const b=t(c,[["render",s]]);export{m as __pageData,b as default};
